// Two independent labels; the account observer sees totals by contract.
workflow IndependentLabels budget 10000 {
    secret priority: boolean max_tokens 1;
    model sentiment = mock("sentiment-v1") max_tokens 16;
    model topic = mock("topic-v1") max_tokens 16;
    prompt sentiment_label() -> text = "Label sentiment: The delivery arrived on time.";
    prompt topic_label() -> text = "Label topic: The delivery arrived on time.";
    if priority {
        let a: text = call sentiment_label() using sentiment;
        let b: text = call topic_label() using topic;
    } else {
        let b: text = call topic_label() using topic;
        let a: text = call sentiment_label() using sentiment;
    }
    output "classification calls complete";
}

// Independent checks can run in either order; neither request uses a response.
workflow DocumentChecks budget 10000 {
    secret confidential_schedule: boolean max_tokens 1;
    model spelling = mock("spelling-check-v1") max_tokens 64;
    model citation = mock("citation-check-v1") max_tokens 64;
    prompt spelling_check() -> text = "Check spelling: The result was reproduced.";
    prompt citation_check() -> text = "Check citation formatting: [Smith 2025].";
    if confidential_schedule {
        let a: text = call spelling_check() using spelling;
        let b: text = call citation_check() using citation;
    } else {
        let b: text = call citation_check() using citation;
        let a: text = call spelling_check() using spelling;
    }
    output "checks complete";
}

// Closed documents, separate calls and no returned text in the public output.
workflow IndependentSummaries budget 10000 {
    secret schedule: boolean max_tokens 1;
    model summarizer = mock("summarizer-v1") max_tokens 64;
    prompt summarize(t: text) -> text = "Summarize: {t}";
    if schedule {
        let a: text = call summarize("Document A: rainfall increased in April.") using summarizer;
        let b: text = call summarize("Document B: the river gauge was repaired.") using summarizer;
    } else {
        let b: text = call summarize("Document B: the river gauge was repaired.") using summarizer;
        let a: text = call summarize("Document A: rainfall increased in April.") using summarizer;
    }
    output "summary calls complete";
}
